const CATEGORY_MAP = {
  expense: ["餐饮", "交通", "购物", "居住", "娱乐", "医疗", "教育", "其他支出"],
  income: ["工资", "奖金", "兼职", "投资收益", "红包", "其他收入"],
};

const TYPE_LABEL = { income: "收入", expense: "支出" };

const state = {
  records: [],
  monthFilter: "all",
  pendingDeleteId: null,
};

const els = {};

function formatMoney(value) {
  const num = Number(value) || 0;
  const sign = num < 0 ? "-" : "";
  const abs = Math.abs(num);
  return sign + "¥" + abs.toFixed(2);
}

function todayISO() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return d.getFullYear() + "-" + m + "-" + day;
}

function monthOf(dateStr) {
  if (typeof dateStr !== "string" || dateStr.length < 7) return "";
  return dateStr.slice(0, 7);
}

function normalizeRecord(raw) {
  const rec = raw && typeof raw === "object" ? raw : {};
  const type = rec.type === "income" ? "income" : "expense";
  const amount = Number(rec.amount);
  return {
    id: typeof rec.id === "string" && rec.id ? rec.id : "rec_" + Math.random().toString(36).slice(2, 10) + Date.now().toString(36),
    date: typeof rec.date === "string" && rec.date ? rec.date : todayISO(),
    type: type,
    category: typeof rec.category === "string" && rec.category ? rec.category : CATEGORY_MAP[type][0],
    amount: Number.isFinite(amount) ? amount : 0,
    note: typeof rec.note === "string" ? rec.note : "",
  };
}

function makeId() {
  return "rec_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8);
}

function fillCategoryOptions(type, selected) {
  const list = CATEGORY_MAP[type] || CATEGORY_MAP.expense;
  els.category.textContent = "";
  list.forEach(function (name) {
    const opt = document.createElement("option");
    opt.value = name;
    opt.textContent = name;
    els.category.appendChild(opt);
  });
  if (selected && list.indexOf(selected) !== -1) {
    els.category.value = selected;
  }
}

function buildMonthOptions() {
  const months = [];
  const seen = {};
  state.records.forEach(function (rec) {
    const m = monthOf(rec.date);
    if (m && !seen[m]) {
      seen[m] = true;
      months.push(m);
    }
  });
  months.sort(function (a, b) { return a < b ? 1 : a > b ? -1 : 0; });

  if (state.monthFilter !== "all" && months.indexOf(state.monthFilter) === -1) {
    state.monthFilter = "all";
  }

  els.monthFilter.textContent = "";
  const allOpt = document.createElement("option");
  allOpt.value = "all";
  allOpt.textContent = "全部月份";
  els.monthFilter.appendChild(allOpt);

  months.forEach(function (m) {
    const opt = document.createElement("option");
    opt.value = m;
    opt.textContent = m.replace("-", " 年 ") + " 月";
    els.monthFilter.appendChild(opt);
  });

  els.monthFilter.value = state.monthFilter;
}

function visibleRecords() {
  if (state.monthFilter === "all") return state.records.slice();
  return state.records.filter(function (rec) {
    return monthOf(rec.date) === state.monthFilter;
  });
}

function computeTotals(list) {
  let income = 0;
  let expense = 0;
  list.forEach(function (rec) {
    if (rec.type === "income") income += rec.amount;
    else expense += rec.amount;
  });
  return { income: income, expense: expense, balance: income - expense, count: list.length };
}

function renderStats(list) {
  const totals = computeTotals(list);
  els.statIncome.textContent = formatMoney(totals.income);
  els.statExpense.textContent = formatMoney(totals.expense);
  els.statBalance.textContent = formatMoney(totals.balance);
  els.statBalanceWrap.classList.toggle("is-negative", totals.balance < 0);
  els.statsNote.textContent = "当前筛选范围内共 " + totals.count + " 条记录";
}

function renderList(list) {
  els.listCount.textContent = list.length + " 条";
  els.recordBody.textContent = "";

  if (list.length === 0) {
    els.emptyHint.hidden = false;
    els.tableWrap.hidden = true;
    els.emptyHint.textContent = state.records.length === 0
      ? "暂无记录，使用上方表单添加第一笔收支。"
      : "当前筛选月份没有记录，可切换月份或选择“全部月份”。";
    return;
  }

  els.emptyHint.hidden = true;
  els.tableWrap.hidden = false;

  const sorted = list.slice().sort(function (a, b) {
    if (a.date === b.date) return a.id < b.id ? 1 : -1;
    return a.date < b.date ? 1 : -1;
  });

  sorted.forEach(function (rec) {
    const tr = document.createElement("tr");

    const tdDate = document.createElement("td");
    tdDate.textContent = rec.date;
    tr.appendChild(tdDate);

    const tdType = document.createElement("td");
    const tag = document.createElement("span");
    tag.className = "tag " + (rec.type === "income" ? "tag-income" : "tag-expense");
    tag.textContent = TYPE_LABEL[rec.type];
    tdType.appendChild(tag);
    tr.appendChild(tdType);

    const tdCat = document.createElement("td");
    tdCat.textContent = rec.category;
    tr.appendChild(tdCat);

    const tdAmount = document.createElement("td");
    tdAmount.className = "cell-amount " + (rec.type === "income" ? "is-income" : "is-expense");
    tdAmount.textContent = (rec.type === "income" ? "+" : "-") + formatMoney(rec.amount).replace("-", "");
    tr.appendChild(tdAmount);

    const tdNote = document.createElement("td");
    tdNote.className = "cell-note";
    tdNote.textContent = rec.note ? rec.note : "—";
    tr.appendChild(tdNote);

    const tdAction = document.createElement("td");
    tdAction.className = "cell-action";
    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "btn btn-ghost btn-mini";
    delBtn.textContent = "删除";
    delBtn.setAttribute("data-role", "delete");
    delBtn.setAttribute("data-id", rec.id);
    tdAction.appendChild(delBtn);
    tr.appendChild(tdAction);

    els.recordBody.appendChild(tr);
  });
}

function render() {
  buildMonthOptions();
  const list = visibleRecords();
  renderStats(list);
  renderList(list);
}

function showError(message) {
  els.formError.textContent = message;
  els.formError.hidden = false;
}

function clearError() {
  els.formError.textContent = "";
  els.formError.hidden = true;
}

async function persist() {
  const current = await appStore.getState();
  const next = Object.assign({}, current, { records: state.records });
  await appStore.setState(next);
}

function openDialog(id) {
  const rec = state.records.find(function (r) { return r.id === id; });
  if (!rec) return;
  state.pendingDeleteId = id;
  els.dialogText.textContent = "确定删除 " + rec.date + " 的" + TYPE_LABEL[rec.type] + "记录（" + rec.category + " " + formatMoney(rec.amount) + "）吗？此操作不可撤销。";
  els.dialogBackdrop.hidden = false;
  els.dialogConfirm.focus();
}

function closeDialog() {
  state.pendingDeleteId = null;
  els.dialogBackdrop.hidden = true;
}

async function confirmDelete() {
  const id = state.pendingDeleteId;
  if (!id) {
    closeDialog();
    return;
  }
  const nextRecords = state.records.filter(function (r) { return r.id !== id; });
  const prevRecords = state.records;
  state.records = nextRecords;
  closeDialog();
  render();
  try {
    await persist();
  } catch (err) {
    state.records = prevRecords;
    render();
    showError("删除失败，数据未保存，请重试。");
  }
}

async function handleSubmit(event) {
  event.preventDefault();
  clearError();

  const date = els.date.value;
  const type = els.type.value === "income" ? "income" : "expense";
  const category = els.category.value;
  const amountRaw = els.amount.value.trim();
  const note = els.note.value.trim();

  if (!date) {
    showError("请选择日期。");
    els.date.focus();
    return;
  }
  if (!category) {
    showError("请选择分类。");
    els.category.focus();
    return;
  }
  if (amountRaw === "") {
    showError("请输入金额。");
    els.amount.focus();
    return;
  }
  const amount = Number(amountRaw);
  if (!Number.isFinite(amount) || amount <= 0) {
    showError("金额必须是大于 0 的数字。");
    els.amount.focus();
    return;
  }

  const record = {
    id: makeId(),
    date: date,
    type: type,
    category: category,
    amount: Math.round(amount * 100) / 100,
    note: note,
  };

  const prevRecords = state.records;
  state.records = prevRecords.concat([record]);
  if (state.monthFilter !== "all" && monthOf(record.date) !== state.monthFilter) {
    state.monthFilter = "all";
  }
  render();

  try {
    await persist();
  } catch (err) {
    state.records = prevRecords;
    render();
    showError("保存失败，记录未写入，请重试。");
    return;
  }

  els.amount.value = "";
  els.note.value = "";
  els.date.value = todayISO();
  els.amount.focus();
}

function resetForm() {
  clearError();
  els.date.value = todayISO();
  els.type.value = "expense";
  fillCategoryOptions("expense", CATEGORY_MAP.expense[0]);
  els.amount.value = "";
  els.note.value = "";
}

async function init() {
  els.date = document.getElementById("field-date");
  els.type = document.getElementById("field-type");
  els.category = document.getElementById("field-category");
  els.amount = document.getElementById("field-amount");
  els.note = document.getElementById("field-note");
  els.monthFilter = document.querySelector('[data-role="month-filter"]');
  els.formError = document.querySelector('[data-role="form-error"]');
  els.statIncome = document.querySelector('[data-role="stat-income"]');
  els.statExpense = document.querySelector('[data-role="stat-expense"]');
  els.statBalance = document.querySelector('[data-role="stat-balance"]');
  els.statBalanceWrap = els.statBalance.closest(".stat");
  els.statsNote = document.querySelector('[data-role="stats-note"]');
  els.listCount = document.querySelector('[data-role="list-count"]');
  els.emptyHint = document.querySelector('[data-role="empty-hint"]');
  els.tableWrap = document.querySelector('[data-role="table-wrap"]');
  els.recordBody = document.querySelector('[data-role="record-body"]');
  els.dialogBackdrop = document.querySelector('[data-role="dialog-backdrop"]');
  els.dialogText = document.querySelector('[data-role="dialog-text"]');
  els.dialogConfirm = document.querySelector('[data-role="dialog-confirm"]');
  els.dialogCancel = document.querySelector('[data-role="dialog-cancel"]');
  els.form = document.querySelector(".entry-form");
  els.resetBtn = document.querySelector('[data-role="reset"]');

  const stored = await appStore.getState();
  const rawRecords = stored && Array.isArray(stored.records) ? stored.records : null;

  if (rawRecords === null) {
    state.records = [];
    await persist();
  } else {
    state.records = rawRecords.map(normalizeRecord);
  }

  resetForm();
  render();

  els.type.addEventListener("change", function () {
    fillCategoryOptions(els.type.value, null);
  });

  els.monthFilter.addEventListener("change", function () {
    state.monthFilter = els.monthFilter.value;
    render();
  });

  els.form.addEventListener("submit", handleSubmit);
  els.resetBtn.addEventListener("click", resetForm);

  els.recordBody.addEventListener("click", function (event) {
    const target = event.target;
    if (!target || !target.getAttribute) return;
    if (target.getAttribute("data-role") !== "delete") return;
    const id = target.getAttribute("data-id");
    if (id) openDialog(id);
  });

  els.dialogCancel.addEventListener("click", closeDialog);
  els.dialogConfirm.addEventListener("click", confirmDelete);

  els.dialogBackdrop.addEventListener("click", function (event) {
    if (event.target === els.dialogBackdrop) closeDialog();
  });

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !els.dialogBackdrop.hidden) closeDialog();
  });
}

await init();

artifact.css:
:root {
  --bg-deep: #0f1b2a;
  --bg-mid: #16283c;
  --bg-soft: #1d3category;
  --panel: rgba(255, 255, 255, 0.06);
  --panel-strong: rgba(255, 255, 255, 0.1);
  --border: rgba(255, 255, 255, 0.14);
  --text: #eaf2fb;
  --text-dim: #9fb3c8;
  --accent: #4cc9a0;
  --accent-strong: #2fae86;
  --income: #4cc9a0;
  --expense: #ff7a7a;
  --balance: #7fb2ff;
  --danger: #ff6b6b;
  --radius: 14px;
  --shadow: 0 18px 40px rgba(0, 0, 0, 0.35);
}

#app {
  min-height: 100vh;
  background: radial-gradient(circle at 12% 8%, #1e3a55 0%, transparent 55%),
    radial-gradient(circle at 88% 0%, #23405c 0%, transparent 50%),
    linear-gradient(160deg, #0f1b2a 0%, #16283c 55%, #101d2c 100%);
  background-attachment: fixed;
  color: var(--text);
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  min-height: 100vh;
  width: 100%;
  padding: 28px 20px 56px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  max-width: 1080px;
  margin: 0 auto;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 22px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, rgba(76, 201, 160, 0.16), rgba(127, 178, 255, 0.12));
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  border-radius: 12px;
  background: linear-gradient(140deg, var(--accent), #3f8fd6);
  color: #06231b;
  font-size: 24px;
  font-weight: 700;
  flex: none;
}

.brand-text h1 {
  margin: 0;
  font-size: 21px;
  letter-spacing: 0.5px;
}

.brand-sub {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--text-dim);
}

.app-main {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px 22px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(6px);
}

.panel-title {
  margin: 0 0 14px;
  font-size: 16px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: 0.4px;
}

.entry-form {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px 16px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.field-wide {
  grid-column: span 2;
}

.field-inline {
  flex-direction: row;
  align-items: center;
  gap: 10px;
}

.field label {
  font-size: 13px;
  color: var(--text-dim);
  font-weight: 500;
}

.field input,
.field select {
  width: 100%;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: rgba(9, 20, 32, 0.72);
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.16s ease, box-shadow 0.16s ease, background 0.16s ease;
}

.field input::placeholder {
  color: #6d8299;
}

.field input:focus,
.field select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(76, 201, 160, 0.22);
  background: rgba(9, 20, 32, 0.9);
}

.field select option {
  background: #12212f;
  color: var(--text);
}

.field input[type="date"]::-webkit-calendar-picker-indicator {
  filter: invert(0.85);
  cursor: pointer;
}

.form-error {
  grid-column: 1 / -1;
  margin: 0;
  padding: 9px 12px;
  border-radius: 10px;
  background: rgba(255, 107, 107, 0.14);
  border: 1px solid rgba(255, 107, 107, 0.4);
  color: #ffc0c0;
  font-size: 13px;
}

.form-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 10px 20px;
  font-size: 14px;
  font-family: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.12s ease, filter 0.16s ease, background 0.16s ease, border-color 0.16s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: linear-gradient(135deg, var(--accent), var(--accent-strong));
  color: #05231a;
}

.btn-primary:hover {
  filter: brightness(1.08);
}

.btn-ghost {
  background: rgba(255, 255, 255, 0.06);
  border-color: var(--border);
  color: var(--text);
}

.btn-ghost:hover {
  background: rgba(255, 255, 255, 0.12);
}

.btn-danger {
  background: linear-gradient(135deg, #ff7a7a, #e04b4b);
  color: #2a0606;
}

.btn-danger:hover {
  filter: brightness(1.08);
}

.btn-mini {
  padding: 5px 12px;
  font-size: 13px;
  border-radius: 8px;
}

.stats-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.stats-head .panel-title {
  margin: 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 16px 18px;
  border-radius: 12px;
  background: var(--panel-strong);
  border: 1px solid var(--border);
}

.stat-label {
  font-size: 13px;
  color: var(--text-dim);
}

.stat-value {
  font-size: 22px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.4px;
}

.stat-income .stat-value {
  color: var(--income);
}

.stat-expense .stat-value {
  color: var(--expense);
}

.stat-balance .stat-value {
  color: var(--balance);
}

.stat-balance.is-negative .stat-value {
  color: var(--expense);
}

.stats-note {
  margin: 12px 0 0;
  font-size: 13px;
  color: var(--text-dim);
}

.list-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.list-head .panel-title {
  margin: 0;
}

.list-count {
  font-size: 13px;
  color: var(--text-dim);
  padding: 3px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid var(--border);
}

.empty-hint {
  margin: 0;
  padding: 26px 16px;
  text-align: center;
  color: var(--text-dim);
  font-size: 14px;
  border: 1px dashed var(--border);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.03);
}

.table-wrap {
  overflow-x: auto;
  border-radius: 12px;
  border: 1px solid var(--border);
}

.record-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 620px;
}

.record-table th,
.record-table td {
  padding: 11px 14px;
  text-align: left;
  font-size: 14px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  vertical-align: middle;
}

.record-table thead th {
  background: rgba(255, 255, 255, 0.07);
  color: var(--text-dim);
  font-weight: 600;
  font-size: 13px;
  white-space: nowrap;
}

.record-table tbody tr:last-child td {
  border-bottom: none;
}

.record-table tbody tr:hover {
  background: rgba(255, 255, 255, 0.05);
}

.col-amount,
.cell-amount {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  white-space: nowrap;
}

.col-action,
.cell-action {
  text-align: right;
  width: 96px;
}

.cell-amount.is-income {
  color: var(--income);
}

.cell-amount.is-expense {
  color: var(--expense);
}

.tag {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}

.tag-income {
  background: rgba(76, 201, 160, 0.18);
  color: var(--income);
  border: 1px solid rgba(76, 201, 160, 0.4);
}

.tag-expense {
  background: rgba(255, 122, 122, 0.16);
  color: var(--expense);
  border: 1px solid rgba(255, 122, 122, 0.38);
}

.cell-note {
  color: var(--text-dim);
  max-width: 220px;
  overflow-wrap: anywhere;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(4, 10, 18, 0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 400px;
  background: #16283c;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.5);
}

.dialog-title {
  margin: 0 0 10px;
  font-size: 17px;
}

.dialog-text {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--text-dim);
  overflow-wrap: anywhere;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 860px) {
  .entry-form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .field-wide {
    grid-column: span 2;
  }
  .stats-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 560px) {
  .app-shell {
    padding: 18px 14px 40px;
  }
